-- PT147-S4-Q6. Batch 05.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch05$PT147-S4-Q6$batch05$ AND q.stimulus=$batch05$Scientist: Laboratory animals have access to ample food, and they get relatively little exercise. These factors can skew the results of research using animals, since such studies often rely on the assumption that the animal subjects are healthy. For instance, animal studies that purport to show that extreme caloric restriction can extend lifespans take for granted that their subjects were not overfed to begin with.$batch05$ AND q.prompt=$batch05$The scientist's argument requires assuming which one of the following?$batch05$ AND q.correct_choice=$batch05$B$batch05$) THEN RAISE EXCEPTION 'Question changed: PT147-S4-Q6'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanation_steps s WHERE s.explanation_id=$batch05$45d92455-5b00-4472-bb31-9a00e8dc6c24$batch05$) <> 0 OR (SELECT COUNT(*) FROM lr_explanation_choice_notes n WHERE n.explanation_id=$batch05$45d92455-5b00-4472-bb31-9a00e8dc6c24$batch05$) <> 0 THEN RAISE EXCEPTION 'Explanation changed: PT147-S4-Q6'; END IF; END $guard$;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e CROSS JOIN (VALUES (0, $batch05$Conclusion$batch05$, $batch05$Ample food and little exercise can skew the results of animal research.$batch05$), (1, $batch05$Evidence$batch05$, $batch05$Lab animals get ample food and little exercise. Many studies assume their subjects are healthy. The caloric restriction studies, for example, assume their animals were not overfed to begin with.$batch05$), (2, $batch05$Evaluate$batch05$, $batch05$The skewing only happens if lab conditions make the animals *unhealthy*. If eating freely and exercising little left them perfectly healthy, the studies' assumption would be true, and nothing would be skewed. The scientist never says the conditions are bad for the animals.$batch05$), (3, $batch05$Goal$batch05$, $batch05$A link: ample food and little exercise can be unhealthy for lab animals.$batch05$)) v(position,label,body) WHERE e.id=$batch05$45d92455-5b00-4472-bb31-9a00e8dc6c24$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch05$A$batch05$, $batch05$This is the most popular wrong answer. It flips the scientist's idea: the scientist needs bad conditions to *cause* poor health, not good conditions to *guarantee* good health. A restricted diet and plenty of exercise could still leave an animal unhealthy for other reasons, and the argument would be fine.$batch05$), ($batch05$B$batch05$, $batch05$Negate it: "these conditions *cannot* be unhealthy for the animals." Then the animals are healthy, the studies' assumption holds, and there is nothing to skew the results.$batch05$), ($batch05$C$batch05$, $batch05$Animals outside the lab are not part of the argument.$batch05$), ($batch05$D$batch05$, $batch05$What some studies take into account does not affect whether the conditions can skew results.$batch05$), ($batch05$E$batch05$, $batch05$How steady their eating habits are says nothing about whether the habits are healthy.$batch05$)) v(letter,body) WHERE q.qid=$batch05$PT147-S4-Q6$batch05$ AND e.id=$batch05$45d92455-5b00-4472-bb31-9a00e8dc6c24$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
